import java.util.*;

class Solution {
    public int[] nextGreaterElement(int[] queries, int[] line) {
        Map<Integer, Integer> next = new HashMap<>();
        Deque<Integer> st = new ArrayDeque<>();   // decreasing values waiting for a taller one
        for (int x : line) {
            while (!st.isEmpty() && st.peek() < x) next.put(st.pop(), x);
            st.push(x);
        }
        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; i++) ans[i] = next.getOrDefault(queries[i], -1);
        return ans;
    }
}

