class Solution:
    def nextGreaterElement(self, queries: List[int], line: List[int]) -> List[int]:
        nxt = {}; st = []
        for x in line:
            while st and st[-1] < x: nxt[st.pop()] = x
            st.append(x)
        return [nxt.get(q, -1) for q in queries]

