function nextGreaterElement(queries, line) {
  const pos = new Map(); line.forEach((v, i) => pos.set(v, i));
  return queries.map((q) => { for (let i = pos.get(q) + 1; i < line.length; i++) if (line[i] > q) return line[i]; return -1; });
}
